package com.nunnun.roommate.entity;
import com.nunnun.user.entity.User; import jakarta.persistence.*; import java.util.Objects; import org.hibernate.annotations.Check;
@Entity @Table(name="roommate_group_members",uniqueConstraints={@UniqueConstraint(columnNames="user_id"),@UniqueConstraint(columnNames={"roommate_group_id","slot_no"}),@UniqueConstraint(columnNames={"roommate_group_id","user_id"})}) @Check(constraints="slot_no IN (1, 2)")
public class RoommateGroupMember { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="roommate_group_id",nullable=false) private RoommateGroup roommateGroup; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="slot_no",nullable=false) private Short slotNo; protected RoommateGroupMember(){} private RoommateGroupMember(RoommateGroup g,User u,short s){roommateGroup=Objects.requireNonNull(g);user=Objects.requireNonNull(u);slotNo=s;} public static RoommateGroupMember join(RoommateGroup g,User u,short s){return new RoommateGroupMember(g,u,s);} public Long getId(){return id;} public RoommateGroup getRoommateGroup(){return roommateGroup;} public User getUser(){return user;} public Short getSlotNo(){return slotNo;} }
